                writer.WriteBoolean("is_commit_specific", overrideTemplate.IsCommitSpecificOption.Value!.Value);

            var targetRawValue = OverrideTemplate.TargetEnumToJsonValue(overrideTemplate.TargetOption.Value!.Value);
            writer.WriteString("target", targetRawValue);
        }
    }
}
